package ThreadExamples;

with Base_Types;

thread PeriodicThread
  features
    Input: in event data port Base_Types::Integer;
    Output: out data port Base_Types::Boolean;
    Trigger: in event port;
  properties
    Dispatch_Protocol => Periodic;
    Period => 10 ms;
    Deadline => 8 ms;
    Priority => 50;
  flows
    DataFlow: flow source Input sink Output;
end PeriodicThread;

